-- composition of rule kernels CoverIdxScan x OrderBySubq (sqlite), template graft_union
CREATE VIEW n1 AS SELECT 7 AS c0 UNION SELECT 1 AS c0;
WITH cte1 AS MATERIALIZED (SELECT MIN (CAST('abc' AS TEXT), CAST('ß' AS TEXT)) AS c0 FROM (SELECT FORMAT ('%s|%s', '{"k": 1, "a": [1, 2]}', '{}') AS c0, '2000-01-01 00:00:00' AS c1 FROM (SELECT * FROM n1 UNION ALL SELECT * FROM n1 WHERE (SELECT count(*) FROM (SELECT '{"k": 1, "a": [1, 2]}' AS c0 FROM tp AS a1 WHERE ((a1.c1, TRUE) <> (CASE WHEN FALSE THEN a1.c1 ELSE CONCAT_WS ('-', FALSE, (SELECT SUM (CAST(5e-324 AS REAL)) FROM t3 AS a2)) END, TRUE)) GROUP BY a1.c0, a1.c1) AS kb) < 0) AS a1 GROUP BY a1.c0) AS a2 WHERE TRUE GROUP BY a2.c1) SELECT 7 AS c0, (-42) AS c1, CAST(100 AS INTEGER) AS c2 FROM cte1 AS a3 WHERE FALSE;
